    /** If True, and ``link`` is also True, pack linked data-blocks into the current blend-file. */
    pack?: H.In<boolean>;
    /** When True the path is stored relative to the open blend file. */
    relative?: H.In<boolean>;
    /** If True, set fake user on appended IDs. */
    set_fake?: H.In<boolean>;
    /** If True, also make indirect dependencies of appended libraries local. */
    recursive?: H.In<boolean>;
    /** If True,try to re-use previously appended matching ID on new append. */
    reuse_local_id?: H.In<boolean>;
    /** If True, only list data-blocks marked as assets. */
    assets_only?: H.In<boolean>;
    /** If True, clear the asset data on append (it is always kept for linked data). */
    clear_asset_data?: H.In<boolean>;
